  "options": [
    {
      "id": "A",
      "text": "$64\\,\\Omega$"
    },
    {
      "id": "B",
      "text": "$32\\,\\Omega$"
    },
    {
      "id": "C",
      "text": "$16\\,\\Omega$"
    },
    {
      "id": "D",
      "text": "$8\\,\\Omega$"
    }
  ],
  "correct": "A",
  "explanation": [
    {
      "title": "Model",
      "content": "Resistance obeys $R=\\rho L/A$."
    },
    {
      "title": "Translate",
      "content": "Doubling length multiplies $R$ by $2$."
    },
    {
      "title": "Compute",
      "content": "Halving radius makes area one-fourth, multiplying $R$ by $4$."
    },
    {
      "title": "Check",
      "content": "Combined factor is $2\\times4=8$."
    },
    {
      "title": "Conclusion",
      "content": "New resistance is $8\\times8=64\\,\\Omega$."
    }
  ],
  "concepts": [
    "numerical-reasoning",
    "advanced network reasoning",
    "template-03"
  ]
