    marksWrong: -1,
    questionText: `For $p(x)=2x+5$, what is the remainder when $p(x)$ is divided by $x-(-2)$?`,
    isPyq: false,
    options: [
      { id: `A`, text: `$5$` },
      { id: `B`, text: `$-4$` },
      { id: `C`, text: `$1$` },
      { id: `D`, text: `$3$` }
    ],
    correct: `C`,
    explanation: [
      { title: `Remainder theorem`, content: `On division by $x-r$, the remainder is $p(r)$.` },
      { title: `Identify divisor root`, content: `Here $x-(-2)=0$ gives $x=-2$.` },
      { title: `Substitute`, content: `$p(-2)=2(-2)+5$.` },
      { title: `Evaluate`, content: `$p(-2)=1$.` },
      { title: `Conclusion`, content: `The remainder is $1$.` }
    ],
    concepts: [`Remainder Theorem`, `polynomial reasoning`, `algebraic structure`]
